/**
 * `validateLayoutBlocks` is generated by the typia transform, which jest does not run, so this spec exercises the
 * build output. `turbo.json` makes `testunit` depend on this package's `build`.
 */
// eslint-disable-next-line @typescript-eslint/no-require-imports
const { validateLayoutBlocks } = require('../../dist/blocks/validateLayoutBlocks') as {
	validateLayoutBlocks: (blocks: unknown, maxBlocks?: number) => { path: string; expected: string }[];
};

const text = (value: string) => ({ type: 'plain_text', text: value });

it('accepts blocks whose elements leave out appId, blockId and actionId', () => {
	expect(
		validateLayoutBlocks([
			{ type: 'section', text: text('hi'), accessory: { type: 'button', text: text('go'), actionId: 'go' } },
			{ type: 'actions', elements: [{ type: 'button', text: text('go') }] },
			{ type: 'divider' },
		]),
	).toEqual([]);
});

it('reports a block that departs from its type', () => {
	const errors = validateLayoutBlocks([{ type: 'header', text: 'not a text object' }]);

	expect(errors.map(({ path }) => path)).toEqual(expect.arrayContaining(['$input[0].text']));
});

it('reports unknown block types', () => {
	expect(validateLayoutBlocks([{ type: 'bogus' }])).not.toEqual([]);
});

it('reports blocks beyond the limit of the message or of the view', () => {
	const blocks = Array.from({ length: 51 }, () => ({ type: 'divider' }));

	expect(validateLayoutBlocks(blocks).map(({ path }) => path)).toEqual(['$input']);
	expect(validateLayoutBlocks(blocks, 100)).toEqual([]);
});

it('reports text beyond its limit', () => {
	expect(validateLayoutBlocks([{ type: 'header', text: text('a'.repeat(151)) }]).map(({ path }) => path)).toEqual(['$input[0].text.text']);
});

it.each([
	{ type: 'checkboxes', options: [{ text: text('A'), value: 'a' }] },
	{ type: 'radio_buttons', options: [{ text: text('A'), value: 'a' }] },
	{ type: 'timepicker' },
])('accepts the alternative element name $type', (element) => {
	expect(validateLayoutBlocks([{ type: 'actions', elements: [element] }])).toEqual([]);
});
